      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Asymptotics",
      "kind": "theorem",
      "type": "∀ {r : ℝ}, 0 < r → Filter.Tendsto (fun x => Real.log x * x ^ r) (nhdsWithin 0 (Set.Ioi 0)) (nhds 0)"
