      "kind": "theorem",
      "type": "∀ {c : ENNReal}, c ≠ ⊤ → ∀ {y : ℝ}, 0 < y → Filter.Tendsto (fun x => c * x ^ y) (nhds 0) (nhds 0)"
    },
    {
      "name": "Asymptotics.isLittleO_pow_sub_sub",
      "module_name": "Mathlib.Analysis.Asymptotics.Lemmas",
      "kind": "theorem",
      "type": "∀ {E' : Type u_6} [inst : SeminormedAddCommGroup E'] (x₀ : E') {m : ℕ},\n  1 < m → (fun x => ‖x - x₀‖ ^ m) =o[nhds x₀] fun x => x - x₀"
    },
    {
      "name": "tendsto_pow_atTop_nhds_zero_of_lt_one",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_4} [inst : Semifield 𝕜] [inst_1 : LinearOrder 𝕜] [IsStrictOrderedRing 𝕜] [ExistsAddOfLE 𝕜] [Archimedean 𝕜]\n  [inst_5 : TopologicalSpace 𝕜] [OrderTopology 𝕜] {r : 𝕜},\n  0 ≤ r → r < 1 → Filter.Tendsto (fun n => r ^ n) Filter.atTop (nhds 0)"
    },
    {
      "name": "tendsto_pow_atTop_nhds_zero_iff",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_4} [inst : Field 𝕜] [inst_1 : LinearOrder 𝕜] [IsStrictOrderedRing 𝕜] [Archimedean 𝕜]\n  [inst_4 : TopologicalSpace 𝕜] [OrderTopology 𝕜] {r : 𝕜},\n  Filter.Tendsto (fun n => r ^ n) Filter.atTop (nhds 0) ↔ |r| < 1"
    },
    {
      "name": "NNReal.tendsto_pow_atTop_nhds_zero_of_lt_one",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {r : NNReal}, r < 1 → Filter.Tendsto (fun n => r ^ n) Filter.atTop (nhds 0)"
    }
  ]
